245			if (!loaded.ok || loaded.value === null) return undefined;
246			candidates.push(Object.freeze({ bytes: Uint8Array.from(loaded.value), ref: Object.freeze({ ...ref }) }));
247		}
248		return Object.freeze(candidates);
