264			if (!page.ok || (page.value.generations.length === 0 && page.value.nextCursor !== null)) return undefined;
265			generations.push(...page.value.generations);
266			if (page.value.nextCursor === null) return Object.freeze(generations);
267			if (seenCursors.has(page.value.nextCursor)) return undefined;
268			seenCursors.add(page.value.nextCursor);
269			cursor = page.value.nextCursor;
