401			.filter((candidate) => candidate?.kind === expectedCurrentProjectionKind);
402		const currentProjection = projections.length === 1 ? projections[0] : undefined;
403		if (
404			currentAnchor === undefined ||
405			successorAnchor === undefined ||
406			currentProjection === undefined ||
407			currentProjection.epoch !== currentEpoch ||
408			typeof currentProjection.artifactDigest !== "string" ||
409			typeof currentProjection.artifactId !== "string" ||
410			typeof currentProjection.blueprintDigest !== "string" ||
411			typeof currentProjection.catalogDigest !== "string" ||
412			typeof currentProjection.runtimeProfile !== "string" ||
413			currentProjection.blueprintDigest !== currentAnchor.blueprintDigest ||
