416			return undefined;
417		}
418		return Object.freeze({
419			currentAnchor,
420			currentEpoch,
421			currentProjectionKind: expectedCurrentProjectionKind,
422			currentTrustRecord,
423			currentCatalog: Object.freeze({
424				artifactDigest: currentProjection.artifactDigest,
425				artifactId: currentProjection.artifactId,
426				blueprintDigest: currentProjection.blueprintDigest,
427				catalogDigest: currentProjection.catalogDigest,
428				runtimeProfile: currentProjection.runtimeProfile,
429			}),
430			cut,
431			successorAnchor,
432			successorAnchorBytes,
433			successorEpoch,
434			successorTrust: opened.trust,
435			successorTrustRecord,
