439	async function verifySnapshot(
440		facts: Pick<SealedAdoptionFacts, "snapshotDeclaration" | "snapshotStore">,
441		chain: VerifiedChain
442	): Promise<VerifiedSnapshot | undefined> {
443		let scope: Awaited<ReturnType<SealedAdoptionFacts["snapshotStore"]["openScope"]>> | undefined;
444		let port: ReturnType<NonNullable<typeof scope>["verificationQuarantine"]["open"]> | undefined;
445		try {
446			const decoded = decodeSnapshotManifest({
447				exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
448				expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
449				profile: PROFILE,
450			});
451			scope = await facts.snapshotStore.openScope(facts.snapshotDeclaration);
452			port = scope.verificationQuarantine.open(new AbortController().signal);
