457				const bytes = await port?.read(selected);
458				if (
459					bytes === undefined ||
460					bytes.byteLength !== selected.byteLength ||
461					snapshotChunkDigest(selected.index, bytes) !== selected.digest
462				) {
463					return undefined;
464				}
465				chunks[selected.index] = Uint8Array.from(bytes);
466				return bytes;
467			};
468			const status = await scope.status();
469			if (status.kind === "verified") {
470				for (const descriptor of decoded.chunks) {
471					if ((await readChunk(descriptor)) === undefined) return undefined;
472				}
473			} else {
474				const verified = verifySnapshotStreamWithReceipt({
475					exactCanonicalManifestBytes: facts.snapshotDeclaration.exactCanonicalManifestBytes,
476					expectedManifestDigest: facts.snapshotDeclaration.scope.manifestDigest,
477					expectedScope: facts.snapshotDeclaration.scope,
478					profile: PROFILE,
479					quarantine: scope.verificationQuarantine,
480					source: Object.freeze({ read: readChunk }),
481				});
482				await verified.completion;
483				await scope.complete(await verified.receipt);
484			}
485			for (const descriptor of decoded.chunks) {
486				if (chunks[descriptor.index] === undefined && (await readChunk(descriptor)) === undefined) return undefined;
487			}
488			if (chunks.length !== decoded.chunks.length || chunks.some((chunk) => chunk === undefined)) return undefined;
489			const payloadBytes = new Uint8Array(chunks.reduce((total, chunk) => total + chunk.byteLength, 0));
