491			for (const chunk of chunks) {
492				payloadBytes.set(chunk, offset);
493				offset += chunk.byteLength;
494			}
495			const payload = canonicalRecord(payloadBytes);
496			const manifest = canonicalRecord(facts.snapshotDeclaration.exactCanonicalManifestBytes);
