502				payload.anchor !== manifest.anchor ||
503				payload.anchor !== chain.cut.previousAnchor ||
504				payload.objectId !== chain.cut.objectId ||
505				payload.epoch !== chain.cut.epoch ||
506				payload.archiveIndexRoot !== chain.cut.archiveIndexRoot ||
507				payload.blueprintDigest !== chain.cut.blueprintDigest ||
508				manifest.stateDigest !== chain.cut.stateDigest ||
509				manifest.aclDigest !== chain.cut.aclDigest ||
510				hex(hashDomain("ts-drp/state/v3", encodeCanonical(payload.application))) !== manifest.stateDigest ||
511				hex(hashDomain("ts-drp/latched-acl/v3", encodeCanonical(payload.acl))) !== manifest.aclDigest
512			) {
513				return undefined;
514			}
515			return Object.freeze({ exactCanonicalPayloadBytes: payloadBytes, manifest, payload });
516		} catch {
517			return undefined;
518		} finally {
