100	function runDeath(
101		selectedBrowser: "chromium" | "firefox" | "webkit",
102		profileDirectory: string,
103		url: string
104	): Promise<void> {
105		return new Promise((resolve, reject) => {
106			const encoded = Buffer.from(
107				JSON.stringify({ browserName: selectedBrowser, mode: "death", profileDirectory, url })
108			).toString("base64url");
109			const child = spawn(process.execPath, [childAsset(), encoded], {
110				detached: true,
111				stdio: ["ignore", "ignore", "pipe", "ipc"],
112			});
113			let stderr = "";
114			let killed = false;
115			let killedPids: readonly number[] = [];
116			const timeout = setTimeout(() => {
117				if (child.pid !== undefined) process.kill(-child.pid, "SIGKILL");
118				reject(new Error(`D.108c browser death timeout: ${stderr}`));
119			}, 30_000);
120			child.stderr?.setEncoding("utf8");
121			child.stderr?.on("data", (value: string) => (stderr += value));
122			child.on("message", (message: ChildMessage) => {
123				if (message.kind === "child-error") reject(new Error(message.message));
124				if (message.kind === "checkpoint" && child.pid !== undefined) {
125					killed = true;
126					const owned = processClosure(captureProcessForest(), child.pid);
127					if (owned.length < 2) throw new TypeError("D.108c browser process forest is empty");
128					killedPids = Object.freeze(owned.map(({ pid }) => pid));
129					const groups = [...new Set(owned.map(({ pgid }) => pgid))].filter((pgid) => pgid > 0 && pgid !== child.pid);
130					for (const pgid of groups) process.kill(-pgid, "SIGKILL");
131					process.kill(-child.pid, "SIGKILL");
132				}
133			});
134			child.once("error", reject);
135			child.once("exit", (code, signal) => {
136				clearTimeout(timeout);
137				if (!killed || signal !== "SIGKILL" || code !== null)
138					reject(new Error(`expected browser SIGKILL, got ${String(code)}/${String(signal)}`));
139				else {
140					const deadline = Date.now() + 10_000;
141					const poll = (): void => {
142						const live = new Set(captureProcessForest().map(({ pid }) => pid));
143						if (killedPids.every((pid) => !live.has(pid))) resolve();
144						else if (Date.now() >= deadline) reject(new Error("D.108c browser process forest survived SIGKILL"));
145						else setTimeout(poll, 25);
146					};
147					poll();
148				}
149			});
150		});
151	}
