684	function creatorSuccessorLiveSeed(
685		facts: SealedAdoptionFacts,
686		closure: RecoveredClosure,
687		chain: VerifiedChain,
688		snapshot: VerifiedSnapshot,
689		resolved: ResolvedBlueprintBytes,
690		projected: Readonly<{ readonly bytes: Uint8Array; readonly descriptor: Readonly<Record<string, unknown>> }>,
691		commitMaterial: NonNullable<ReturnType<typeof successorCommitMaterial>>
692	): CreatorSuccessorLiveSeed | undefined {
693		try {
694			const predecessorProjection = closure.currentCandidates.filter(
695				({ bytes, ref }) =>
696					canonicalRecord(bytes)?.kind === chain.currentProjectionKind && sameRef(ref, commitMaterial.predecessorLiveRef)
697			);
698			const exactCanonicalLatchedAclBytes = encodeCanonical(snapshot.payload.acl);
