739					exactCanonicalAnchorPreimageBytes: Uint8Array.from(
740						chain.currentTrustRecord.exactCanonicalCurrentAnchorPreimageBytes
741					),
742					exactCanonicalProjectionBytes: Uint8Array.from(predecessorProjection[0]?.bytes as Uint8Array),
743					head: Object.freeze({ ...facts.currentHead }),
744					references: Object.freeze(facts.currentReferences.map((ref) => Object.freeze({ ...ref }))),
745					trust: facts.currentTrust,
746					trustRef: Object.freeze({ ...facts.closeResult.currentTrustRef }),
747				}),
748				predecessorExactCanonicalLatchedAclBytes: Uint8Array.from(facts.exactCanonicalLatchedAclBytes),
749				snapshotPayloadDigest: snapshot.manifest.payloadDigest,
750				sourceRuntimeHandle: facts.sourceRuntimeHandle,
751				stateDigest: snapshot.manifest.stateDigest,
752				store: facts.store,
753				successor: Object.freeze({
754					candidates: Object.freeze(successorCandidates),
755					detachedAnchorSignature: Uint8Array.from(chain.successorTrustRecord.detachedCurrentAnchorSignature),
756					exactCanonicalAnchorPreimageBytes: Uint8Array.from(chain.successorAnchorBytes),
757					exactCanonicalProjectionBytes: Uint8Array.from(projected.bytes),
758					references: Object.freeze(commitMaterial.candidateReferences.map((ref) => Object.freeze({ ...ref }))),
759					trust: chain.successorTrust,
760					trustRef: Object.freeze({ ...facts.closeResult.successorTrustRef }),
761				}),
762				terminalizeSource: facts.terminalizeSource,
