627	function successorCommitMaterial(
628		facts: SealedAdoptionFacts,
629		closure: RecoveredClosure,
630		exactCanonicalProjectionBytes: Uint8Array,
631		predecessorKind: VerifiedChain["currentProjectionKind"]
632	):
633		| Readonly<{
634				readonly candidateReferences: readonly GenerationRef[];
635				readonly generationId: GenerationId;
636				readonly predecessorLiveRef: GenerationRef;
637		  }>
638		| undefined {
639		try {
640			const predecessors = closure.currentCandidates.filter(({ bytes, ref }) => {
641				const decoded = canonicalRecord(bytes);
642				return decoded?.kind === predecessorKind && facts.proposedReferences.some((candidate) => sameRef(candidate, ref));
643			});
644			if (predecessors.length !== 1) return undefined;
645			const predecessorLiveRef = predecessors[0]?.ref;
646			if (predecessorLiveRef === undefined) return undefined;
647			const projectionDigest = digestBlob(exactCanonicalProjectionBytes);
648			if (!projectionDigest.ok) return undefined;
649			const projectionRef = Object.freeze({
650				byteLength: exactCanonicalProjectionBytes.byteLength,
651				digest: projectionDigest.value,
652			});
653			const predecessorAclDigest = digestBlob(facts.exactCanonicalLatchedAclBytes);
654			if (!predecessorAclDigest.ok) return undefined;
655			const predecessorAclRef = Object.freeze({
656				byteLength: facts.exactCanonicalLatchedAclBytes.byteLength,
657				digest: predecessorAclDigest.value,
658			});
659			const retained = facts.proposedReferences.filter((candidate) => !sameRef(candidate, predecessorLiveRef));
660			const candidateReferences = Object.freeze(
661				[
662					...retained,
663					projectionRef,
664					...(retained.some((candidate) => sameRef(candidate, predecessorAclRef)) ? [] : [predecessorAclRef]),
665				].sort((left, right) => (left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0))
666			);
667			if (
668				!candidateReferences.some((candidate) => sameRef(candidate, predecessorAclRef)) ||
669				new Set(candidateReferences.map(({ digest }) => digest)).size !== candidateReferences.length
670			) {
671				return undefined;
672			}
673			const random = new Uint8Array(32);
674			crypto.getRandomValues(random);
675			const parsed = parseGenerationId(hex(random));
676			return parsed.ok
677				? Object.freeze({ candidateReferences, generationId: parsed.value, predecessorLiveRef })
678				: undefined;
679		} catch {
680			return undefined;
681		}
682	}
