684	function creatorSuccessorLiveSeed(
685		facts: SealedAdoptionFacts,
686		closure: RecoveredClosure,
687		chain: VerifiedChain,
688		snapshot: VerifiedSnapshot,
689		resolved: ResolvedBlueprintBytes,
690		projected: Readonly<{ readonly bytes: Uint8Array; readonly descriptor: Readonly<Record<string, unknown>> }>,
