692	): CreatorSuccessorLiveSeed | undefined {
693		try {
694			const predecessorProjection = closure.currentCandidates.filter(
695				({ bytes, ref }) =>
696					canonicalRecord(bytes)?.kind === chain.currentProjectionKind && sameRef(ref, commitMaterial.predecessorLiveRef)
697			);
698			const exactCanonicalLatchedAclBytes = encodeCanonical(snapshot.payload.acl);
699			if (
700				predecessorProjection.length !== 1 ||
701				hex(hashDomain("ts-drp/latched-acl/v3", exactCanonicalLatchedAclBytes)) !== chain.successorAnchor.aclDigest ||
